## `app.js`

```javascript
/**
 * =============================================
 * TASK MANAGEMENT APPLICATION
 * =============================================
 * A vanilla JavaScript app that lets users create,
 * manage, and persist tasks using localStorage.
 * Tasks are grouped by status in a Kanban-style board.
 * =============================================
 */

// ==================== STATE MANAGEMENT ====================

/**
 * Application state object.
 * Holds the current list of tasks and the active filter.
 */
const state = {
  tasks: [],       // Array of task objects
  filter: 'all',   // Current filter: 'all' | 'pending' | 'in_progress' | 'completed'
};

// ==================== LOCAL STORAGE ====================

/**
 * Key used in localStorage for persisting tasks.
 */
const STORAGE_KEY = 'task_manager_tasks';

/**
 * Loads tasks from localStorage into state.tasks.
 * If no data exists, initializes with an empty array.
 */
function loadTasks() {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    state.tasks = stored ? JSON.parse(stored) : [];
  } catch (error) {
    console.error('Failed to load tasks from localStorage:', error);
    state.tasks = [];
  }
}

/**
 * Saves the current state.tasks array to localStorage.
 */
function saveTasks() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state.tasks));
  } catch (error) {
    console.error('Failed to save tasks to localStorage:', error);
  }
}

// ==================== TASK CREATION ====================

/**
 * Generates a unique ID for a new task using timestamp + random suffix.
 * @returns {string} Unique task ID
 */
function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
}

/**
 * Creates a new task object from form input.
 * @param {string} title - Task title
 * @param {string} description - Task description
 * @returns {object} New task object
 */
function createTask(title, description) {
  return {
    id: generateId(),
    title: title.trim(),
    description: description.trim(),
    status: 'pending', // Default status
    createdAt: new Date().toISOString(),
  };
}

/**
 * Adds a new task to state and persists it.
 * @param {string} title
 * @param {string} description
 */
function addTask(title, description) {
  const task = createTask(title, description);
  state.tasks.push(task);
  saveTasks();
  renderBoard();
}

// ==================== TASK STATUS TOGGLE ====================

/**
 * Cycles a task's status: pending → in_progress → completed → pending.
 * @param {string} taskId - ID of the task to toggle
 */
function toggleTaskStatus(taskId) {
  const task = state.tasks.find((t) => t.id === taskId);
  if (!task) return;

  // Cycle through statuses
  const statusOrder = ['pending', 'in_progress', 'completed'];
  const currentIndex = statusOrder.indexOf(task.status);
  task.status = statusOrder[(currentIndex + 1) % statusOrder.length];

  saveTasks();
  renderBoard();
}

// ==================== TASK DELETION ====================

/**
 * Removes a task from state by ID and persists the change.
 * @param {string} taskId - ID of the task to delete
 */
function deleteTask(taskId) {
  // Prevent deleting the last element during iteration by filtering first
  state.tasks = state.tasks.filter((t) => t.id !== taskId);
  saveTasks();
  renderBoard();
}

// ==================== FORMATTING HELPERS ====================

/**
 * Formats an ISO date string into a readable local date.
 * @param {string} isoDate - ISO 8601 date string
 * @returns {string} Formatted date (e.g., "Jan 15, 2025")
 */
function formatDate(isoDate) {
  const date = new Date(isoDate);
  return date.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  });
}

/**
 * Returns the human-readable label for a status string.
 * @param {string} status
 * @returns {string}
 */
function getStatusLabel(status) {
  const labels = {
    pending: 'Pending',
    in_progress: 'In Progress',
    completed: 'Completed',
  };
  return labels[status] || status;
}

// ==================== RENDERING ====================

/**
 * Renders the entire task board based on current state.
 * Groups tasks by status, applies the active filter,
 * and updates column counts.
 */
function renderBoard() {
  // Get references to all task list containers
  const pendingList = document.getElementById('list-pending');
  const inProgressList = document.getElementById('list-in-progress');
  const completedList = document.getElementById('list-completed');

  // Clear existing content
  pendingList.innerHTML = '';
  inProgressList.innerHTML = '';
  completedList.innerHTML = '';

  // Apply filter: determine which statuses to show
  let filteredTasks = state.tasks;
  if (state.filter !== 'all') {
    filteredTasks = state.tasks.filter((t) => t.status === state.filter);
  }

  // Group tasks by status for rendering
  const pendingTasks = filteredTasks.filter((t) => t.status === 'pending');
  const inProgressTasks = filteredTasks.filter((t) => t.status === 'in_progress');
  const completedTasks = filteredTasks.filter((t) => t.status === 'completed');

  // Render each group into its column
  renderTaskList(pendingList, pendingTasks);
  renderTaskList(inProgressList, inProgressTasks);
  renderTaskList(completedList, completedTasks);

  // Update count badges
  updateCountBadge('count-pending', state.tasks.filter((t) => t.status === 'pending').length);
  updateCountBadge('count-in-progress', state.tasks.filter((t) => t.status === 'in_progress').length);
  updateCountBadge('count-completed', state.tasks.filter((t) => t.status === 'completed').length);

  // Show/hide empty state message
  toggleEmptyState(filteredTasks.length === 0 && state.tasks.length > 0);
}

/**
 * Renders a list of task cards into a given container.
 * @param {HTMLElement} container - The DOM element to append cards to
 * @param {Array<object>} tasks - Array of task objects
 */
function renderTaskList(container, tasks) {
  if (tasks.length === 0) {
    // Show a subtle placeholder when the column is empty
    const placeholder = document.createElement('p');
    placeholder.className = 'column-empty';
    placeholder.textContent = 'No tasks here';
    placeholder.style.cssText = `
      text-align: center; color: #b2bec3; font-size: 0.85rem;
      padding: 1rem 0; pointer-events: none;
    `;
    container.appendChild(placeholder);
    return;
  }

  tasks.forEach((task) => {
    const card = createTaskCard(task);
    container.appendChild(card);
  });
}

/**
 * Creates a DOM element representing a single task card.
 * @param {object} task - Task object
 * @returns {HTMLElement} The task card div
 */
function createTaskCard(task) {
  const card = document.createElement('div');
  card.className = `task-card ${task.status === 'completed' ? 'completed' : ''}`;
  card.setAttribute('data-status', task.status);
  card.setAttribute('data-id', task.id);

  // Title
  const titleEl = document.createElement('div');
  titleEl.className = 'task-title';
  titleEl.textContent = task.title;

  // Description (only if it exists)
  let descEl = null;
  if (task.description) {
    descEl = document.createElement('p');
    descEl.className = 'task-desc';
    descEl.textContent = task.description;
  }

  // Meta row: date + status label + delete button
  const metaEl = document.createElement('div');
  metaEl.className = 'task-meta';

  const dateEl = document.createElement('span');
  dateEl.className = 'task-date';
  dateEl.textContent = formatDate(task.createdAt);

  const statusLabel = document.createElement('span');
  statusLabel.className = `status-label ${task.status === 'in_progress' ? 'in-progress' : task.status}`;
  statusLabel.textContent = getStatusLabel(task.status);

  // Delete button
  const deleteBtn = document.createElement('button');
  deleteBtn.className = 'btn-delete';
  deleteBtn.innerHTML = '🗑️';
  deleteBtn.title = 'Delete task';
  deleteBtn.setAttribute('aria-label', `Delete task: ${task.title}`);

  metaEl.appendChild(dateEl);
  metaEl.appendChild(statusLabel);
  metaEl.appendChild(deleteBtn);

  // Assemble card
  card.appendChild(titleEl);
  if (descEl) card.appendChild(descEl);
  card.appendChild(metaEl);

  // Click on card toggles status
  card.addEventListener('click', (e) => {
    // Don't toggle if the delete button was clicked
    if (!e.target.closest('.btn-delete')) {
      toggleTaskStatus(task.id);
    }
  });

  // Delete button click handler
  deleteBtn.addEventListener('click', (e) => {
    e.stopPropagation(); // Prevent triggering the card's toggle
    deleteTask(task.id);
  });

  return card;
}

/**
 * Updates the text of a count badge element.
 * @param {string} elementId - ID of the badge element
 * @param {number} count - New count value
 */
function updateCountBadge(elementId, count) {
  const badge = document.getElementById(elementId);
  if (badge) {
    badge.textContent = count;
  }
}

/**
 * Shows or hides the empty state message.
 * @param {boolean} show - Whether to show the empty state
 */
function toggleEmptyState(show) {
  const emptyState = document.getElementById('empty-state');
  if (emptyState) {
    emptyState.style.display = show ? 'block' : 'none';
  }
}

// ==================== EVENT LISTENERS ====================

/**
 * Handles the "Add Task" form submission.
 * Prevents default form behavior, reads input values,
 * validates, and adds the task.
 */
function handleFormSubmit(event) {
  event.preventDefault();

  const titleInput = document.getElementById('task-title');
  const descInput = document.getElementById('task-desc');

  const title = titleInput.value.trim();
  const description = descInput.value.trim();

  // Basic validation
  if (!title) {
    titleInput.focus();
    return;
  }

  addTask(title, description);

  // Reset form
  titleInput.value = '';
  descInput.value = '';
  titleInput.focus();
}

/**
 * Handles filter button clicks.
 * Updates the active filter in state and re-renders the board.
 * @param {string} filterValue - The filter value from the clicked button
 */
function handleFilterClick(filterValue) {
  state.filter = filterValue;

  // Update active button styling
  document.querySelectorAll('.btn-filter').forEach((btn) => {
    btn.classList.toggle('active', btn.getAttribute('data-filter') === filterValue);
  });

  renderBoard();
}

// ==================== INITIALIZATION ====================

/**
 * Sets up all event listeners and performs the initial render.
 * Called once when the DOM is fully loaded.
 */
function init() {
  // Load persisted tasks from localStorage
  loadTasks();

  // Attach form submit handler
  const form = document.getElementById('task-form');
  if (form) {
    form.addEventListener('submit', handleFormSubmit);
  }

  // Attach filter button handlers (event delegation on the container)
  const filterSection = document.querySelector('.filter-buttons');
  if (filterSection) {
    filterSection.addEventListener('click', (event) => {
      const btn = event.target.closest('.btn-filter');
      if (btn) {
        handleFilterClick(btn.getAttribute('data-filter'));
      }
    });
  }

  // Set the initial active filter button
  const initialFilterBtn = document.querySelector(
    `.btn-filter[data-filter="${state.filter}"]`
  );
  if (initialFilterBtn) {
    initialFilterBtn.classList.add('active');
  }

  // Perform the first render
  renderBoard();
}

// Start the app when the DOM is ready
document.addEventListener('DOMContentLoaded', init);
