/* =============================================
   GERENCIADOR DE TAREFAS — app.js
   Aplicação completa em JavaScript puro (vanilla)
   com persistência via localStorage.
   ============================================= */

// =============================================
// 1. CONSTANTES E CONFIGURAÇÕES
// =============================================

/** Chave usada no localStorage para salvar as tarefas */
const STORAGE_KEY = 'task_manager_tasks';

/** Status válidos de uma tarefa */
const STATUSES = {
  PENDENTE: 'pendente',
  EM_ANDAMENTO: 'em_andamento',
  CONCLUÍDO: 'concluído'
};

/** Ícones e labels para cada status (usados na UI) */
const STATUS_CONFIG = {
  [STATUSES.PENDENTE]:    { icon: '🟡', label: 'Pendentes' },
  [STATUSES.EM_ANDAMENTO]: { icon: '🔵', label: 'Em Andamento' },
  [STATUSES.CONCLUÍDO]:    { icon: '🟢', label: 'Concluídos' }
};

/** Ordem de exibição das seções */
const STATUS_ORDER = [STATUSES.PENDENTE, STATUSES.EM_ANDAMENTO, STATUSES.CONCLUÍDO];

// =============================================
// 2. ESTADO DA APLICAÇÃO
// =============================================

/** Filtro atual aplicado (padrão: todas) */
let currentFilter = 'todas';

/** Mapa de seções colapsadas por status (collapsed[status] = true/false) */
let collapsedSections = {
  [STATUSES.PENDENTE]: false,
  [STATUSES.EM_ANDAMENTO]: false,
  [STATUSES.CONCLUÍDO]: false
};

// =============================================
// 3. FUNÇÕES DE PERSISTÊNCIA (localStorage)
// =============================================

/**
 * Carrega as tarefas do localStorage.
 * Retorna array vazio se não houver dados ou se houver erro de parse.
 */
function loadTasks() {
  try {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  } catch (error) {
    console.error('Erro ao carregar tarefas do localStorage:', error);
    return [];
  }
}

/**
 * Salva as tarefas no localStorage.
 * @param {Array} tasks - Array de objetos de tarefa
 */
function saveTasks(tasks) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
  } catch (error) {
    console.error('Erro ao salvar tarefas no localStorage:', error);
  }
}

// =============================================
// 4. FUNÇÕES DE CRIAÇÃO E MANIPULAÇÃO
// =============================================

/**
 * Gera um ID único para cada tarefa usando timestamp + random.
 * @returns {string} ID único
 */
function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
}

/**
 * Cria um novo objeto de tarefa.
 * @param {string} title   - Título da tarefa
 * @param {string} description - Descrição da tarefa (opcional)
 * @returns {Object} Tarefa criada
 */
function createTask(title, description = '') {
  return {
    id: generateId(),
    title: title.trim(),
    description: description.trim(),
    status: STATUSES.PENDENTE, // Padrão: pendente
    createdAt: new Date().toISOString()
  };
}

/**
 * Adiciona uma nova tarefa ao estado e salva.
 * @param {string} title   - Título da tarefa
 * @param {string} description - Descrição da tarefa
 */
function addTask(title, description) {
  const tasks = loadTasks();
  const newTask = createTask(title, description);
  tasks.push(newTask);
  saveTasks(tasks);
  showToast('Tarefa adicionada com sucesso!', 'success');
  return newTask;
}

/**
 * Alterna o status da tarefa ciclando: pendente → em_andamento → concluído → pendente.
 * @param {string} taskId - ID da tarefa
 */
function toggleTaskStatus(taskId) {
  const tasks = loadTasks();
  const taskIndex = tasks.findIndex(t => t.id === taskId);

  if (taskIndex === -1) return;

  // Ciclo de status
  const currentStatus = tasks[taskIndex].status;
  let newStatus;

  if (currentStatus === STATUSES.PENDENTE) {
    newStatus = STATUSES.EM_ANDAMENTO;
  } else if (currentStatus === STATUSES.EM_ANDAMENTO) {
    newStatus = STATUSES.CONCLUÍDO;
  } else {
    newStatus = STATUSES.PENDENTE;
  }

  tasks[taskIndex].status = newStatus;
  saveTasks(tasks);
  renderTasks();
}

/**
 * Exclui uma tarefa pelo ID.
 * @param {string} taskId - ID da tarefa a ser excluída
 */
function deleteTask(taskId) {
  let tasks = loadTasks();
  const task = tasks.find(t => t.id === taskId);
  tasks = tasks.filter(t => t.id !== taskId);
  saveTasks(tasks);
  showToast(`"${task?.title || 'Tarefa'}" excluída!`, 'error');
  renderTasks();
}

/**
 * Filtra as tarefas com base no filtro atual.
 * @param {Array} tasks - Array de todas as tarefas
 * @returns {Array} Tarefas filtradas
 */
function filterTasks(tasks) {
  if (currentFilter === 'todas') return tasks;
  return tasks.filter(t => t.status === currentFilter);
}

// =============================================
// 5. FUNÇÕES DE FORMATAÇÃO
// =============================================

/**
 * Formata uma data ISO para exibição em português.
 * @param {string} isoDate - Data no formato ISO 8601
 * @returns {string} Data formatada
 */
function formatDate(isoDate) {
  const date = new Date(isoDate);
  return date.toLocaleDateString('pt-BR', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  });
}

/**
 * Escapa caracteres HTML para prevenir XSS.
 * @param {string} text - Texto cru
 * @returns {string} Texto seguro para inserção no DOM
 */
function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

// =============================================
// 6. FUNÇÕES DE RENDERIZAÇÃO (UI)
// =============================================

/**
 * Renderiza todas as seções de tarefas na tela.
 * Agrupa por status e aplica o filtro atual.
 */
function renderTasks() {
  const container = document.getElementById('tasks-container');
  const tasks = loadTasks();
  const filtered = filterTasks(tasks);

  // Limpa o container
  container.innerHTML = '';

  // Se não houver tarefas filtradas, mostra estado vazio
  if (filtered.length === 0) {
    container.innerHTML = `
      <div class="empty-state">
        <div class="empty-icon">📭</div>
        <p>${currentFilter === 'todas' ? 'Nenhuma tarefa cadastrada ainda.' : 'Nenhuma tarefa encontrada neste filtro.'}</p>
      </div>
    `;
    return;
  }

  // Renderiza uma seção para cada status (na ordem definida)
  STATUS_ORDER.forEach(status => {
    // Se o filtro for diferente de "todas", só mostra a seção correspondente
    if (currentFilter !== 'todas' && currentFilter !== status) return;

    const tasksInStatus = filtered.filter(t => t.status === status);
    if (tasksInStatus.length === 0) return; // Não renderiza seções vazias

    const config = STATUS_CONFIG[status];
    const isCollapsed = collapsedSections[status];

    // Cria o elemento da seção
    const section = document.createElement('section');
    section.className = `status-section${isCollapsed ? ' collapsed' : ''}`;
    section.setAttribute('data-status', status);

    // Monta o HTML interno
    section.innerHTML = `
      <div class="status-header" data-toggle="${status}">
        <h2 class="status-title">
          ${config.icon} ${config.label}
          <span class="status-count">${tasksInStatus.length}</span>
        </h2>
        <span class="status-toggle">▼</span>
      </div>
      <div class="tasks-list"></div>
    `;

    // Preenche a lista de tarefas dentro da seção
    const tasksList = section.querySelector('.tasks-list');
    tasksInStatus.forEach(task => {
      tasksList.appendChild(createTaskCard(task));
    });

    container.appendChild(section);
  });

  // Adiciona event listeners para colapsar/expandir seções
  document.querySelectorAll('[data-toggle]').forEach(btn => {
    btn.addEventListener('click', (e) => {
      // Evita toggle ao clicar em botões dentro do header
      if (e.target.closest('.btn-delete')) return;
      const status = btn.getAttribute('data-toggle');
      collapsedSections[status] = !collapsedSections[status];
      renderTasks();
    });
  });
}

/**
 * Cria um elemento DOM (cartão) para uma tarefa.
 * @param {Object} task - Objeto da tarefa
 * @returns {HTMLElement} Cartão da tarefa
 */
function createTaskCard(task) {
  const card = document.createElement('div');
  card.className = `task-card${task.status === STATUSES.CONCLUÍDO ? ' concluded' : ''}`;
  card.setAttribute('data-status', task.status);
  card.setAttribute('data-id', task.id);

  // Ícone indicativo do status ao clicar
  const statusIcon = {
    [STATUSES.PENDENTE]: '📌',
    [STATUSES.EM_ANDAMENTO]: '⏳',
    [STATUSES.CONCLUÍDO]: '✅'
  };

  card.innerHTML = `
    <span class="task-click-hint">${statusIcon[task.status]}</span>
    <div class="task-content">
      <h3>${escapeHtml(task.title)}</h3>
      ${task.description ? `<p>${escapeHtml(task.description)}</p>` : ''}
      <div class="task-date">Criada em ${formatDate(task.createdAt)}</div>
    </div>
    <button class="btn-delete" data-delete="${task.id}" title="Excluir tarefa" aria-label="Excluir ${escapeHtml(task.title)}">
      🗑️
    </button>
  `;

  // Clique no cartão alterna o status da tarefa
  card.addEventListener('click', (e) => {
    // Não alterna se clicar no botão de excluir
    if (e.target.closest('.btn-delete')) return;
    toggleTaskStatus(task.id);
  });

  // Clique no botão de excluir remove a tarefa
  const deleteBtn = card.querySelector('.btn-delete');
  deleteBtn.addEventListener('click', (e) => {
    e.stopPropagation(); // Evita que o clique no cartão dispare o toggle
    if (confirm(`Deseja excluir a tarefa "${task.title}"?`)) {
      deleteTask(task.id);
    }
  });

  return card;
}

// =============================================
// 7. FUNÇÕES DE NOTIFICAÇÃO (Toast)
// =============================================

/**
 * Exibe uma notificação toast temporária na tela.
 * @param {string} message - Mensagem a exibir
 * @param {string} type    - Tipo: 'success', 'error' ou 'info'
 */
function showToast(message, type = 'info') {
  const container = document.createElement('div');
  container.className = 'toast-container';

  const toast = document.createElement('div');
  toast.className = `toast ${type}`;
  toast.textContent = message;

  container.appendChild(toast);
  document.body.appendChild(container);

  // Remove o toast após a animação (3s)
  setTimeout(() => {
    container.remove();
  }, 3000);
}

// =============================================
// 8. INICIALIZAÇÃO E EVENT LISTENERS
// =============================================

/**
 * Configura todos os event listeners da aplicação.
 */
function initEventListeners() {
  // --- Formulário de adição de tarefas ---
  const form = document.getElementById('task-form');
  form.addEventListener('submit', (e) => {
    e.preventDefault();

    const titleInput = document.getElementById('task-title');
    const descInput = document.getElementById('task-desc');

    const title = titleInput.value.trim();
    const description = descInput.value.trim();

    // Validação básica
    if (!title) {
      showToast('O título é obrigatório!', 'error');
      titleInput.focus();
      return;
    }

    addTask(title, description);

    // Limpa o formulário
    form.reset();
    titleInput.focus();
  });

  // --- Botões de filtro ---
  const filterButtons = document.querySelectorAll('.btn-filter');
  filterButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      // Atualiza classe ativa em todos os botões
      filterButtons.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');

      // Atualiza o filtro e re-renderiza
      currentFilter = btn.getAttribute('data-filter');
      renderTasks();
    });
  });
}

/**
 * Inicializa a aplicação quando o DOM estiver pronto.
 */
document.addEventListener('DOMContentLoaded', () => {
  initEventListeners();
  renderTasks();
});
